import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Set<String> changed = new HashSet<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            if (parts[1].equals(parts[2])) continue;        // 変わっていない
            changed.add(parts[0]);
        }
        List<String[]> order = List.of(
                new String[] {"runtime", "ZERO_MIGRATION regression-test"},
                new String[] {"feature", "SPEC_MIGRATION guide-and-code"},
                new String[] {"java", "JAVA_MIGRATION compatibility-test"},
                new String[] {"dependency", "LIBRARY_MIGRATION release-notes"});
        boolean any = false;
        for (String[] row : order) {
            if (changed.contains(row[0])) {
                System.out.println(row[1]);
                any = true;
            }
        }
        if (!any) System.out.println("NO_CHANGE");
    }
}

