import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int m = Integer.parseInt(sc.nextLine().trim());
        Map<String, String> support = new HashMap<>();
        for (int i = 0; i < m; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            support.put(parts[0], parts[1]);
        }
        int k = Integer.parseInt(sc.nextLine().trim());
        Set<String> blocked = new TreeSet<>();
        Set<String> unknown = new TreeSet<>();
        for (int i = 0; i < k; i++) {
            String feature = sc.nextLine().trim();
            String state = support.get(feature);
            if (state == null) unknown.add(feature);
            else if (state.equals("UNSUPPORTED")) blocked.add(feature);
        }
        for (String feature : blocked) System.out.println("BLOCKED " + feature);
        for (String feature : unknown) System.out.println("UNKNOWN " + feature);
        System.out.println(blocked.isEmpty() && unknown.isEmpty() ? "READY" : "NOT_READY");
    }
}

