import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        Map<String, String> before = read(sc);
        Map<String, String> after = read(sc);

        Set<String> names = new TreeSet<>();
        names.addAll(before.keySet());
        names.addAll(after.keySet());

        boolean upgraded = false;
        for (String name : names) {
            String was = before.get(name), now = after.get(name);
            if (was == null) {
                System.out.println("ADDED " + name + "-" + now);
            } else if (now == null) {
                System.out.println("REMOVED " + name + "-" + was);
            } else if (!was.equals(now)) {
                System.out.println("UPGRADED " + name + " " + was + " -> " + now);
                upgraded = true;
            }
        }
        System.out.println(upgraded ? "SPEC_MIGRATION" : "ZERO_MIGRATION");
    }

    static Map<String, String> read(Scanner sc) {
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, String> map = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            String feature = line.substring(line.indexOf('>') + 1, line.lastIndexOf('<'));
            int dash = feature.lastIndexOf('-');
            map.put(feature.substring(0, dash), feature.substring(dash + 1));
        }
        return map;
    }
}

