import java.util.*;

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        boolean livenessDown = false, readinessDown = false;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            boolean down = parts[1].equals("DOWN");
            if (!down) continue;
            if (parts[2].equals("Liveness")) livenessDown = true;
            else readinessDown = true;
        }
        if (livenessDown) {
            System.out.println("LIVENESS=DOWN READINESS=DOWN ACTION=RESTART");
        } else if (readinessDown) {
            System.out.println("LIVENESS=UP READINESS=DOWN ACTION=STOP_TRAFFIC");
        } else {
            System.out.println("LIVENESS=UP READINESS=UP ACTION=NONE");
        }
    }
}
